(1, 1, 1, 1, 'أحمد عبد الستار (فني تشغيل أول)', '2026-11-21 00:00:00', '08:00 - 09:00', 3450, 28, 95.8, 12, 0, NULL, 'تشغيل منتظم ومراقبة جودة التغليف.', 'الأداء ممتاز والماكينة تعمل بكفاءة تشغيلية مثالية أعلى من 90%. يوصى بالحفاظ على نفس معدل التغذية ونظافة السير.', 1, 4, '2026-11-21 20:58:52', '2026-11-21 20:58:52'),
(2, 1, 1, 1, 'أحمد عبد الستار (فني تشغيل أول)', '2026-11-21 00:00:00', '09:00 - 10:00', 3520, 28.5, 97.7, 8, 0, NULL, 'تشغيل منتظم ومراقبة جودة التغليف.', 'الأداء ممتاز والماكينة تعمل بكفاءة تشغيلية مثالية أعلى من 90%. يوصى بالحفاظ على نفس معدل التغذية ونظافة السير.', 1, 4, '2026-11-21 20:58:52', '2026-11-21 20:58:52'),
(3, 1, 1, 1, 'أحمد عبد الستار (فني تشغيل أول)', '2026-11-21 00:00:00', '10:00 - 11:00', 2800, 24, 77.8, 35, 12, 'انحشار رول السيلوفان في سكينة اللحام الحراري', 'تم تنظيف فكوك اللحام وإعادة معايرة الفوتوسيل واستئناف السرعة الطبيعية.', 'الكفاءة متوسطة (مقبولة). تم رصد تفاوت طفيف في معدل الإنتاج؛ يرجى فحص ضغط الهواء وتوافق سرعة السير. ارتفاع ملحوظ في الهادر (35 وحدة)؛ يوصى بضبط سكينة القص وحرارة لحام السيلوفان فوراً لمنع هدر الخامات.', 1, 4, '2026-11-21 20:58:52', '2026-11-21 20:58:52'),
(4, 1, 1, 1, 'أحمد عبد الستار (فني تشغيل أول)', '2026-11-21 00:00:00', '11:00 - 12:00', 3600, 29, 100, 5, 0, NULL, 'تشغيل منتظم ومراقبة جودة التغليف.', 'الأداء ممتاز والماكينة تعمل بكفاءة تشغيلية مثالية أعلى من 90%. يوصى بالحفاظ على نفس معدل التغذية ونظافة السير.', 1, 4, '2026-11-21 20:58:52', '2026-11-21 20:58:52'),
